/* HandC thermal studio prototype. Transactions are local, simulated and role guarded. */
(() => {
  'use strict';
  const H=HandC, STORE='handc-thermal-v2', SESSION='handc-thermal-session', PASSWORD='HandCDemo2026!';
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let db,session=null,theme='night',language='en',scene='pools',pending=null,returnTo='home',selectedMember='jamie',camera=null,frame=null,toastTimer,modalTrigger=null;
  try{const stored=JSON.parse(localStorage.getItem(STORE));db=H.validDatabase(stored)?stored:H.seed();localStorage.setItem(STORE,JSON.stringify(db));theme=localStorage.getItem('handc-theme')==='day'?'day':'night';language=localStorage.getItem('handc-locale')==='zh-TW'?'zh-TW':'en';session=JSON.parse(sessionStorage.getItem(SESSION)||localStorage.getItem(SESSION))}catch{db=H.seed()}
  const t=key=>language==='zh-TW'?(window.HandCChinese?.[key]||key):key;
  const user=()=>H.actor(db,session?.userId);
  const isStaff=()=>H.staff(user()),canSell=()=>H.seller(user()),isAdmin=()=>user()?.role==='admin';
  const locale=()=>language==='zh-TW'?'zh-TW':'en-MY';
  const rm=amount=>'RM'+new Intl.NumberFormat('en-MY',{maximumFractionDigits:2}).format(amount);
  const date=stamp=>new Intl.DateTimeFormat(locale(),{timeZone:H.ZONE,day:'numeric',month:'short',year:'numeric'}).format(stamp);
  const time=stamp=>new Intl.DateTimeFormat('en-MY',{timeZone:H.ZONE,hour:'numeric',minute:'2-digit',hour12:true}).format(stamp);
  const stamp=value=>date(value)+' · '+time(value);
  const name=id=>db.users.find(u=>u.id===id)?.name||t('Member');
  const pName=p=>t(H.product(p.productId||p.id)?.name||'Pass');
  const hours=p=>p.start===18?'6pm–9pm':p.end===12?'9am–12pm':'9am–9pm';
  const roleName=role=>t(({admin:'Admin',reception:'Reception',attendant:'Studio attendant',member:'Member'})[role]||'Member');
  const failMessage=code=>t(({
    'member-required':'Choose an active member.','sale-forbidden':'Reception or admin access is required.','entry-forbidden':'Staff access is required.','admin-required':'Admin access is required.',
    'founding-sold-out':'All 200 founding passes have been allocated.','same-membership-active':'You already have an active pass of this type.','invalid-visit-date':'Choose a visit date within the next 90 days.',
    'window-ended':'This access window has ended. Choose another date.','already-inside':'This member is already checked in. Check out before another entry.','studio-closed':'Entry is available from 9am to 9pm, Malaysia time.',
    'admissions-paused':'Admissions are temporarily paused. Please speak to reception.','capacity-reached':'The configured occupancy limit has been reached.','no-valid-pass':'No pass is valid for entry right now.',
    'already-checked-out':'This visit is already checked out.','invalid-capacity':'Enter a whole-number capacity from 1 to 200, or leave it empty.','invalid-enquiry':'Check your name, email, group size and preferred date.',
    'storage-failed':'Changes could not be saved. Please try again.','request-conflict':'This purchase request is no longer valid. Please start again.'
  })[code]||'Unable to complete this action. Please try again.');
  const icons={arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M7 7h3v3H7zm7 0h3v3h-3zm-7 7h3v3H7zm7 0h3v3h-3z"/>',water:'<path d="M12 3C9 7 5 11 5 15a7 7 0 0 0 14 0c0-4-4-8-7-12Z"/><path d="M8 15a4 4 0 0 0 4 4"/>',heat:'<path d="M6 20V8m6 12V4m6 16V8M3 20h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4Z"/><path d="M15 5v3m0 3v2m0 3v3"/>',home:'<path d="m3 10 9-7 9 7v11h-7v-7h-4v7H3Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z"/>',check:'<path d="m5 12 4 4 10-10"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M17 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v2"/>'};
  const icon=key=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[key]||icons.arrow}</svg>`;
  const button=(label,action,extra='',kind='')=>`<button class="button ${kind}" data-action="${action}" ${extra}>${t(label)} ${icon('arrow')}</button>`;
  const link=(label,route,kind='')=>`<a class="button ${kind}" href="#${route}">${t(label)} ${icon('arrow')}</a>`;
  const pill=(label,kind='')=>`<span class="pill ${kind}">${t(label)}</span>`;
  function notify(message,kind='info'){window.HandCExperience?.feedback(kind);$('#toast').textContent=t(message);$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
  function translate(root){
    if(language==='en')return;
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
    while(node=walker.nextNode()){if(node.parentElement?.closest('[data-raw],script,style'))continue;const key=node.textContent.trim();if(window.HandCChinese?.[key])node.textContent=node.textContent.replace(key,window.HandCChinese[key])}
    root.querySelectorAll('[placeholder],[aria-label]').forEach(el=>{for(const a of ['placeholder','aria-label']){const key=el.getAttribute(a);if(window.HandCChinese?.[key])el.setAttribute(a,window.HandCChinese[key])}});
  }
  async function update(change){
    const run=()=>{
      let latest=db;try{const value=JSON.parse(localStorage.getItem(STORE));if(H.validDatabase(value))latest=value}catch{}
      const result=change(latest),next=result.db||result;
      try{localStorage.setItem(STORE,JSON.stringify(next))}catch{const err=new Error('storage-failed');err.code='storage-failed';throw err}
      db=next;return result;
    };
    return navigator.locks?.request?navigator.locks.request(STORE,{mode:'exclusive'},run):run();
  }
  function stopCamera(){if(frame)cancelAnimationFrame(frame);frame=null;if(camera)camera.getTracks().forEach(track=>track.stop());camera=null}
  function closeModal(){stopCamera();$('#modal').close();pending=null}
  function modal(title,body){
    if(!$('#modal').open)modalTrigger=document.activeElement;
    $('#modal-content').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${t(title)}</h2><button class="icon-button close" data-action="close" aria-label="Close dialog">×</button></div>${body}`;
    translate($('#modal-content'));if(!$('#modal').open)$('#modal').showModal();
  }
  $('#modal').addEventListener('close',()=>{stopCamera();pending=null;const el=modalTrigger;if(el?.isConnected)el.focus({preventScroll:true})});
  $('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal()}});
  const sceneImage=(which='pools',cls='',priority=false)=>`<img class="${cls}" data-scene="${which}" src="assets/studio/${which}-${theme}.webp" alt="${e(t(which==='pools'?'Cold-plunge pools and communal sauna concept':which==='sauna'?'Timber sauna concept':'Reception and refreshments counter concept'))}" width="1672" height="941" decoding="async" ${priority?'fetchpriority="high"':'loading="lazy"'}>`;
  const pageHead=(index,title,description,action='')=>`<div class="page-head"><div><p class="micro">${index}</p><h1 tabindex="-1">${t(title)}</h1><p class="muted">${t(description)}</p></div>${action}</div>`;
  const includes=()=>`<div class="inclusions"><span>${icon('heat')}<span>Communal sauna</span></span><span>${icon('water')}<span>Both plunge pools</span></span></div>`;
  function passCard(p,index){
    const annual=p.id==='founding',left=H.foundingRemaining(db),active=user()&&db.passes.some(pass=>pass.userId===user().id&&pass.productId===p.id&&p.kind!=='entry'&&pass.validUntil>Date.now());
    return `<article class="pass-card ${annual?'founding':''}" id="product-${p.id}"><div class="pass-card-top"><span class="micro">( ${String(index+1).padStart(2,'0')} )</span>${pill(p.kind==='entry'?'Single entry':annual?'Limited to 200':'Unlimited entries')}</div><h3>${t(p.name)}</h3><p class="pass-tag muted">${t(p.tag)}</p><div class="pass-price"><span class="currency">RM</span><strong>${new Intl.NumberFormat('en-MY').format(p.price)}</strong><span>${t(p.kind==='entry'?'per entry':p.kind==='annual'?'per year':p.days===7?'for 7 days':'for 30 days')}</span></div><div class="pass-access"><span>${icon('clock')}${hours(p)}</span><span>${t(p.kind==='entry'?'One visit on your chosen date':'Unlimited entries during access hours')}</span></div>${includes()}<p class="pass-validity">${p.kind==='entry'?t(p.end===12?'Departure by 12pm. No re-entry.':'Departure by 9pm. No re-entry.'):t(p.kind==='annual'?'One year from purchase.':'Validity begins at purchase.')}</p>${annual?`<div class="allocation"><span>Founding allocation</span><strong>${left} / 200</strong></div><p class="micro muted">Demo availability</p>`:''}<button class="button" data-action="buy" data-product="${p.id}" ${annual&&!left||active?'disabled':''}>${t(active?'Already active':annual&&!left?'Sold out':annual?'Become a founding member':'Get this pass')} ${icon('arrow')}</button></article>`;
  }
  function catalogue(){return pageHead('( 01 ) THE PASS COLLECTION','A little time. A lot of reset.','One studio. Sauna and both cold-plunge pools included.')+`<div class="section-heading"><h2>Day passes</h2><span class="micro">ONE VISIT / YOUR CHOSEN DATE</span></div><div class="pass-grid">${H.CATALOG.slice(0,3).map(passCard).join('')}</div><div class="section-heading space-top"><h2>Make it a ritual.</h2><span class="micro">UNLIMITED ENTRIES / 9AM–9PM</span></div><div class="pass-grid memberships">${H.CATALOG.slice(3).map((p,i)=>passCard(p,i+3)).join('')}</div><div class="info-strip"><span>${icon('clock')}<span>Duration passes start at purchase, including purchases made outside access hours.</span></span><span>All times are Malaysia time.</span></div><section class="group-strip"><div><p class="micro">BETTER WITH COMPANY</p><h2>A shared reset.</h2><p class="muted">Planning a group visit or private session? Tell reception what you have in mind.</p></div>${button('Enquire about a group visit','group','','secondary')}</section>`}
  function visitSummary(v){return `<span class="pill ${Date.now()>v.leaveBy?'danger':'positive'}">${t(Date.now()>v.leaveBy?'Departure due':'Checked in')}</span><h2>${pName(v)}</h2><p><span>Entered</span> ${time(v.inAt)} <span class="muted">/</span> <span>Leave by</span> ${time(v.leaveBy)}</p>`}
  function frontPage(){
    const spaces=[
      {id:'pools',word:'Cold.',index:'01',micro:'TWO TEMPERATURES / ONE SHARED SPACE',title:'A clear head. A fresh start.',copy:'Two communal plunge pools. Target temperatures of 4°C and 8°C.',dial:'04° / 08°',note:'TEMPERATURE TARGETS'},
      {id:'sauna',word:'Heat.',index:'02',micro:'COMMUNAL SAUNA / TIMBER WARMTH',title:'Warmth, without the rush.',copy:'Shared sauna access. Warm timber. A little space to slow down.',dial:'H / C',note:'COMMUNAL SAUNA'},
      {id:'reception',word:'Reset.',index:'03',micro:'ARRIVE / REFRESH / RECONNECT',title:'A moment that is yours.',copy:'Arrive, change, reset and refresh. A simple ritual in Raja Uda.',dial:'9–9',note:'DAILY ACCESS HOURS'}
    ];
    return `<section class="public-hero motion-front"><div class="hero-kicker"><span class="micro"><i class="red-dot"></i> THERMAL WELLNESS / RAJA UDA</span><button class="motion-button" data-experience="motion" aria-pressed="false">Pause motion</button></div>
      <div class="hero-copy"><h1 tabindex="-1"><span class="hero-headline"><span class="hero-word">${t('Cold.')}</span> <span class="hero-word heat-word">${t('Heat.')}</span></span><span class="hero-tagline">${t('A moment to reset.')}</span></h1><div class="hero-invitation"><p class="muted">${t('A shared space for cold plunges, sauna sessions and a slower kind of day.')}</p>${link('Find your pass','passes')}</div></div>
      <div class="sequence-track"><div class="thermal-stage" data-step="0" data-visible="true" role="region" aria-label="${t('Cold, heat and reset studio sequence')}">
        <div class="stage-film">${spaces.map((space,i)=>`<article class="scene-panel scene-${space.id}" data-scene-panel data-active="${i===0}" aria-hidden="${i!==0}"><div class="scene-visual">${sceneImage(space.id,'',i===0)}</div><div class="scene-shade"></div><div class="scene-atmosphere" aria-hidden="true"></div><div class="stage-topline"><span class="micro">HANDC / ${space.index}</span><span class="micro">${t('CONCEPT VISUAL')} / ${theme.toUpperCase()}</span></div><div class="thermal-instrument" aria-hidden="true"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="43"/><circle class="dial-dashes" cx="50" cy="50" r="36"/><path class="dial-needle" d="M50 50 71 24"/><circle class="dial-pin" cx="50" cy="50" r="3"/></svg><strong>${space.dial}</strong><span>${t(space.note)}</span></div><div class="stage-caption"><span class="stage-word" aria-hidden="true">${t(space.word)}</span><div><p class="micro">${t(space.micro)}</p><h2>${t(space.title)}</h2><p>${t(space.copy)}</p></div></div></article>`).join('')}</div>
        <div class="stage-navigation"><span class="micro stage-scroll-hint">${t('SCROLL TO EXPERIENCE')} ↓</span><div role="group" aria-label="${t('Studio spaces')}">${spaces.map((space,i)=>`<button data-experience="stage" data-step="${i}" aria-pressed="${i===0}" aria-label="${t('View '+space.id)}"><span class="mono">0${i+1}</span> ${t(space.word)}<i aria-hidden="true"></i></button>`).join('')}</div><span class="micro stage-location">RAJA UDA / PENANG</span></div>
      </div></div>
      <div class="hero-facts" data-reveal><div><strong>9–9</strong><span>Daily access hours</span></div><div><strong>04° / 08°</strong><span>Plunge temperature targets</span></div><div><strong>RM30</strong><span>Sunrise or Sunset entry</span></div><div><strong>200</strong><span>Founding annual passes</span></div></div></section>
      <section class="intro-section" data-reveal><p class="micro">SHARED WELLNESS. PERSONAL SPACE.</p><h2>Cold water.<br>Warm company.</h2><div><p class="muted">An independent neighbourhood studio in Raja Uda. Come for a quiet moment, bring a friend, and build a ritual that feels like yours.</p>${includes()}<p class="small muted">Concept visuals show the planned studio. Temperatures are design targets.</p></div></section>
      <section data-reveal><div class="section-heading"><div><p class="micro">YOUR FIRST GOOD RITUAL</p><h2>A pass for your pace.</h2></div><a class="text-link" href="#passes">${t('See all six passes')} ↗</a></div><div class="pass-grid">${H.CATALOG.slice(0,3).map(passCard).join('')}</div></section>
      <section class="group-strip" data-reveal><div><p class="micro">A REASON TO RETURN</p><h2>Make it part of your week.</h2><p class="muted">Weekly, monthly and founding memberships include unlimited entries during studio hours.</p></div>${link('Explore memberships','passes','secondary')}</section>`;
  }
  function home(){
    const member=user()?.role==='member'?user():null,passes=member?H.currentPasses(db,member.id):[],visit=member?H.inside(db).find(v=>v.userId===member.id):null;
    if(member)return `<div class="member-intro"><div><p class="micro">RAJA UDA / YOUR DAILY RESET</p><h1 tabindex="-1">${t('Good to see you,')} <span data-raw>${e(member.name.split(' ')[0])}.</span></h1><p class="muted">Cold water. Warm company. A little more balance.</p></div><span class="micro" data-clock>${date(Date.now())}</span></div><div class="member-hero"><div class="member-hero-copy"><p class="micro"><i class="red-dot"></i> ${t('YOUR NEXT GOOD RITUAL')}</p>${visit?visitSummary(visit):`<h2>${t('Your time.')}<br><span class="muted">${t('Well spent.')}</span></h2><p class="muted">${t(passes.length?'Your pass is ready for your next visit.':'Make room for a little reset.')}</p>`}<div class="actions">${button('Show entry code','qr')}${link(passes.length?'View my passes':'Explore passes',passes.length?'wallet':'passes','secondary')}</div><p class="small muted">Reception confirms each entry and departure.</p></div><div class="member-hero-image">${sceneImage('pools','',true)}<span class="photo-label">STUDIO CONCEPT / ${theme==='day'?'DAY':'NIGHT'}</span></div></div><div class="section-heading"><h2>Your passes, at a glance.</h2><a class="text-link" href="#wallet">${t('View all passes')} ↗</a></div><div class="member-pass-grid">${passes.length?passes.slice(0,2).map(p=>walletTicket(p,true)).join(''):`<div class="empty-state"><h3>No active passes yet.</h3><p>Choose a day pass or make it a regular ritual.</p>${link('Explore passes','passes')}</div>`}</div><div class="home-bottom"><section><p class="micro">01 / ARRIVE</p><h3>Keep your code close.</h3><p class="muted">Show your member code at reception. Your eligible membership is used before a single-entry pass.</p>${button('Show entry code','qr','','text-button')}</section><section><p class="micro">02 / RESET</p><h3>Two temperatures. One space.</h3><p class="muted">A communal sauna and both plunge pools are included with every pass.</p>${link('Explore the studio','studio','text-button')}</section><section><p class="micro">03 / REFRESH</p><h3>Stay a little longer.</h3><p class="muted">Juice and smoothies are planned at reception. The menu and prices will be announced.</p></section></div>`;
    return frontPage();
  }
  function statusLabel(state){return t(({'ready':'Ready for entry','outside-hours':'Outside access hours','upcoming':'Upcoming','used':'Entry used','expired':'Expired','unavailable':'Unavailable'})[state])}
  function walletTicket(pass,compact=false){
    const p=H.product(pass.productId),state=H.passState(pass),current=['ready','upcoming','outside-hours'].includes(state);
    return `<article class="wallet-ticket ${p.kind==='entry'?'day-ticket':'duration-ticket'} ${!current?'past-ticket':''}"><div class="ticket-head"><span class="micro">HANDC / ${p.kind==='entry'?'SINGLE ENTRY':'UNLIMITED ACCESS'}</span>${pill(statusLabel(state),state==='ready'?'positive':'')}</div><h2>${pName(pass)}</h2><div class="ticket-access"><strong>${hours(p)}</strong><span>${t(p.kind==='entry'?'Single entry':'Unlimited entries')}</span></div><div class="ticket-perforation"></div><dl class="ticket-details">${p.kind==='entry'?`<div><dt>Visit date</dt><dd>${date(H.at(pass.visitDate,12))}</dd></div>`:`<div><dt>Purchased</dt><dd>${stamp(pass.purchasedAt)}</dd></div>`}<div><dt>${p.kind==='entry'?'Departure by':'Valid until'}</dt><dd>${p.kind==='entry'?time(pass.validUntil):stamp(pass.validUntil)}</dd></div></dl>${current?button('Show entry code','qr',`data-member="${pass.userId}"`,'secondary'):''}${compact?'':`<p class="small muted"><span>All facilities included.</span> ${t(p.kind==='entry'?'One admission. No re-entry.':'Validity runs continuously from purchase.')}</p><button class="text-link" data-action="pass-details" data-pass="${pass.id}">Pass details ↗</button>`}</article>`;
  }
  function wallet(){const passes=db.passes.filter(p=>p.userId===user().id),current=passes.filter(p=>p.validUntil>Date.now()&&!p.usedAt),past=passes.filter(p=>!current.includes(p));return pageHead('( 02 ) YOUR PASS WALLET','Your space. Your pace.','All your passes, with the details that matter.',button('Show entry code','qr','','secondary'))+`<div class="wallet-grid">${current.length?current.map(p=>walletTicket(p)).join(''):`<div class="empty-state"><h2>No active passes yet.</h2><p>A little time for yourself is one pass away.</p>${link('Get a pass','passes')}</div>`}</div>${past.length?`<details class="past-passes"><summary>${t('Past passes')} <span>${past.length}</span></summary><div class="wallet-grid">${past.map(p=>walletTicket(p)).join('')}</div></details>`:''}<p class="inline-note">Weekly, monthly and annual passes allow unlimited entries from 9am to 9pm while valid. Reception records every entry and departure.</p>`}
  function visits(){const visits=db.visits.filter(v=>v.userId===user().id),orders=db.orders.filter(o=>o.userId===user().id);return pageHead('( 03 ) YOUR RECORD','Every reset, recorded.','Your entries, departures and pass purchases.')+`<section class="panel"><div class="section-heading"><h2>Visit history</h2><span class="micro">${visits.length} ${t('VISITS')}</span></div>${visits.length?`<div class="record-list">${visits.map(v=>`<article><span class="record-icon">${icon('water')}</span><div><strong>${pName(v)}</strong><p class="muted small">${date(v.inAt)} / ${time(v.inAt)} → ${v.outAt?time(v.outAt):t('Still inside')}</p></div>${pill(v.outAt?'Completed':'Checked in',v.outAt?'':'positive')}</article>`).join('')}</div>`:`<div class="empty-state compact"><h3>Your first visit starts here.</h3><p>Your visits will appear after reception confirms entry.</p></div>`}</section><section class="panel space-top"><div class="section-heading"><h2>Purchase history</h2></div>${orders.length?`<div class="record-list">${orders.map(o=>`<article><span class="record-icon">${icon('ticket')}</span><div><strong>${pName(o)}</strong><p class="muted small">${stamp(o.at)} / <span data-raw>${e(o.id.slice(0,11).toUpperCase())}</span></p></div><strong class="mono">${rm(o.amount)}</strong></article>`).join('')}</div>`:`<p class="muted">No purchases yet.</p>`}</section>`}
  function studio(){return pageHead('( 04 ) THE STUDIO','Quiet materials. Visible purpose.','Cold plunges, communal sauna and space to slow down.')+`<div class="studio-tabs" role="group" aria-label="Studio concept views">${[['pools','Cold pools'],['sauna','Sauna'],['reception','Reception']].map(([id,label])=>`<button data-action="scene" data-scene="${id}" aria-pressed="${scene===id}">${t(label)}</button>`).join('')}</div><figure class="studio-gallery">${sceneImage(scene,'',true)}<figcaption><span class="micro">${t(scene==='pools'?'TWO TEMPERATURES / ONE SHARED SPACE':scene==='sauna'?'COMMUNAL SAUNA / TIMBER WARMTH':'ARRIVE / REFRESH / RECONNECT')}</span><span class="micro muted">CONCEPT VISUAL</span></figcaption></figure><div class="studio-info"><section><p class="micro">01 / THE FACILITIES</p><h2>Heat. Cold. Repeat.</h2>${includes()}<p class="muted">Two communal plunge pools with target temperatures of 4°C and 8°C, alongside a shared sauna.</p><p class="small muted">Concept temperatures and facility capacities remain subject to verification.</p></section><section><p class="micro">02 / YOUR VISIT</p><dl class="fact-list"><div><dt>Location</dt><dd>Raja Uda, Butterworth, Penang</dd></div><div><dt>Access hours</dt><dd>9am–9pm</dd></div><div><dt>Included with every pass</dt><dd>Sauna and both plunge pools</dd></div><div><dt>Refreshments</dt><dd>Juice and smoothie menu to be announced</dd></div></dl></section></div><section class="group-strip"><div><p class="micro">COME TOGETHER</p><h2>Bring your people.</h2><p class="muted">Group and private visits are subject to reception review and operating capacity.</p></div>${button('Enquire about a group visit','group','','secondary')}</section><div class="studio-update"><span class="micro">STUDIO INFORMATION</span><p>The full address, contact channels and refreshments menu will be added when confirmed.</p></div>`}
  function auth(mode='login'){
    const register=mode==='register';return `<section class="auth-layout"><aside class="auth-visual">${sceneImage(theme==='day'?'pools':'sauna','',true)}<div><span class="micro">RAJA UDA / THERMAL WELLNESS</span><h2>${t('A little more')}<br>${t('balance.')}</h2><p>Cold plunges. Communal sauna. A moment for yourself.</p><span class="micro">CONCEPT VISUAL / ${theme.toUpperCase()}</span></div></aside><div class="auth-form-panel"><div class="micro auth-index"><span>${register?'02 / JOIN THE CLUB':'01 / MEMBER ACCESS'}</span><i class="red-dot"></i></div><h1 tabindex="-1">${t(register?'Make room for a reset.':'Welcome back.')}</h1><p class="muted">${t(register?'Create a sample profile to explore HandC.':'Sign in to your HandC demo account.')}</p><form id="auth-form" data-form="${register?'register':'login'}">${register?`<label>Full name<input name="name" required maxlength="60" autocomplete="name" placeholder="Your name"></label>`:''}<label>Email address<input name="email" type="email" required maxlength="100" autocomplete="username" autocapitalize="none" placeholder="you@example.com"></label><label>Password<div class="password-input"><input name="password" type="password" required minlength="8" maxlength="100" autocomplete="${register?'new-password':'current-password'}" placeholder="${t(register?'Choose a demo password':'Enter your password')}"><button type="button" class="password-toggle" data-action="password" aria-label="Show password">◉</button></div></label>${register?'':`<label class="checkbox"><input type="checkbox" name="remember"><span>Keep me signed in</span></label>`}<p class="form-error" role="alert"></p><button class="button" type="submit">${t(register?'Create demo account':'Sign in')} ${icon('arrow')}</button></form><p class="auth-alternate">${t(register?'Already have an account?':'New to HandC?')} <a href="#${register?'login':'register'}">${t(register?'Sign in':'Create a demo account')}</a></p><p class="small muted">Preview accounts only. Do not use a real password.</p>${register?'':`<details class="demo-options"><summary>Try a demo account <span class="micro">DEMO +</span></summary><div class="demo-account-list">${['jamie','admin','reception','attendant'].map(id=>{const u=db.users.find(u=>u.id===id);return `<button data-action="demo-fill" data-member="${u.id}"><span><strong>${roleName(u.role)}</strong><small data-raw>${u.email}</small></span>${icon('arrow')}</button>`}).join('')}</div><p class="small muted"><span>Shared demo password</span>: <code data-raw>${PASSWORD}</code></p></details>`}</div></section>`;
  }
  function account(){const u=user();return pageHead('( 05 ) YOUR ACCOUNT','Your place in the club.','Profile, member code and access details.')+`<div class="account-grid"><section class="member-identity panel"><div class="initials">${e(u.name.split(/\s+/).map(v=>v[0]).slice(0,2).join(''))}</div><span class="micro">${roleName(u.role)}</span><h2 data-raw>${e(u.name)}</h2><p data-raw class="muted">${e(u.email)}</p>${u.number?`<span class="mono">${u.number}</span>${button('Show entry code','qr')}`:''}<button class="text-link" data-action="logout">Sign out ↗</button></section><section class="panel"><h2>Profile details</h2><form data-form="profile"><label>Full name<input name="name" required maxlength="60" value="${e(u.name)}" autocomplete="name"></label><label>Phone number (optional)<input name="phone" type="tel" maxlength="24" value="${e(u.phone||'')}" autocomplete="tel" placeholder="+60"></label><p class="form-error" role="alert"></p><button class="button" type="submit">Save profile ${icon('arrow')}</button></form><div class="account-note"><h3>Your membership, clearly.</h3><p class="muted">Every pass includes the sauna and both plunge pools. Your purchased pass determines access hours, validity and entry allowance.</p></div></section></div>`}
  function metric(label,value,note=''){return `<div class="metric"><span>${t(label)}</span><strong>${value}</strong>${note?`<small>${t(note)}</small>`:''}</div>`}
  function memberSelect(){return `<label>Member<select name="memberId">${db.users.filter(u=>u.role==='member'&&u.active!==false).map(u=>`<option value="${u.id}" ${u.id===selectedMember?'selected':''}>${e(u.name)} / ${u.number}</option>`).join('')}</select></label>`}
  function activeVisits(){return H.inside(db).map(v=>`<tr><td><strong data-raw>${e(name(v.userId))}</strong><small>${pName(v)}</small></td><td class="mono">${time(v.inAt)}</td><td class="mono">${time(v.leaveBy)}${Date.now()>v.leaveBy?pill('Departure due','danger'):''}</td><td><button class="small-button" data-action="checkout" data-visit="${v.id}">Confirm departure</button></td></tr>`).join('')}
  function table(headers,body,empty='No records yet.'){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${t(h)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="empty-cell">${t(empty)}</td></tr>`}</tbody></table></div>`}
  function staffOverview(){
    const today=H.dateKey(),entries=db.visits.filter(v=>H.dateKey(v.inAt)===today),sales=db.orders.filter(o=>H.dateKey(o.at)===today),overdue=H.inside(db).filter(v=>v.leaveBy<Date.now()).length;
    return pageHead('( 01 ) THE STUDIO DESK','A clear view of today.','Raja Uda / entries, departures and the daily rhythm.',link('Open entry desk','staff-entry'))+`<div class="metric-grid">${metric('Inside now',H.inside(db).length,db.settings.capacity?'Configured limit: '+db.settings.capacity:'Occupancy limit not configured')}${metric('Entries today',entries.length,'Every entry is recorded')}${metric('Departures due',overdue,'Check the departure list')}${canSell()?metric('Demo sales today',rm(sales.reduce((n,o)=>n+o.amount,0)),'Simulated purchases'):metric('Studio hours','9–9','Malaysia time')}</div><section class="panel"><div class="section-heading"><h2>Currently inside</h2>${pill(db.settings.admissionsPaused?'Admissions paused':'Demo admissions open',db.settings.admissionsPaused?'danger':'positive')}</div>${table(['Member','Entry','Leave by','Action'],activeVisits(),'No members are checked in.')}</section><div class="staff-bottom-grid"><section class="panel"><p class="micro">FOUNDING MEMBERSHIP</p><h2>${H.foundingRemaining(db)} <span class="muted">/ 200</span></h2><p class="muted">Annual passes remaining in this demo allocation.</p><p class="small muted">A founding pass is allocated only when a purchase is saved.</p></section><section class="panel"><p class="micro">STUDIO OPERATIONS</p><h2>Keep the space clear.</h2><p class="muted">Review admissions, facility availability and the current occupancy limit.</p>${link('Studio controls','staff-studio','secondary')}</section></div>`;
  }
  function entryDesk(){
    const m=db.users.find(u=>u.id===selectedMember&&u.role==='member')||db.users.find(u=>u.role==='member');selectedMember=m.id;
    const preview=H.entryPreview(db,m.id),visit=preview.visit;
    return pageHead('( 02 ) ENTRY & DEPARTURE','A warm welcome. A clear record.','Validate a pass, confirm entry, and record departure.',button('Scan entry code','scan','','secondary'))+`<div class="entry-layout"><section class="panel"><form data-form="lookup"><label>Member number or QR content<input name="code" placeholder="HC0001" required maxlength="180" autocomplete="off"></label><p class="form-error" role="alert"></p><button class="button secondary" type="submit">Find member ${icon('arrow')}</button></form><div class="entry-divider"><span>Or select a member</span></div><form data-form="entry-member">${memberSelect()}<button class="button secondary" type="submit">Review access ${icon('arrow')}</button></form></section><section class="panel entry-review"><div class="section-heading"><span class="micro">ACCESS REVIEW</span>${pill(preview.error?(visit?'Already inside':'Entry unavailable'):'Ready for entry',preview.error?(visit?'positive':'danger'):'positive')}</div><h2 data-raw>${e(m.name)}</h2><p class="mono muted">${m.number}</p>${preview.error?`<p class="entry-message">${e(failMessage(preview.error))}</p>${visit?`<dl class="fact-list"><div><dt>Entered</dt><dd>${time(visit.inAt)}</dd></div><div><dt>Leave by</dt><dd>${time(visit.leaveBy)}</dd></div></dl>${button('Confirm departure','checkout',`data-visit="${visit.id}"`)}`:canSell()?button('Sell a pass','sell',`data-member="${m.id}"`,'secondary'):''}`:`<div class="entry-pass"><span>Pass to use</span><h3>${pName(preview.pass)}</h3><p>${t(preview.product.kind==='entry'?'This entry will use the single-entry pass.':'Unlimited entry. Your membership stays active.')}</p><dl class="fact-list"><div><dt>Leave by</dt><dd>${stamp(preview.leaveBy)}</dd></div><div><dt>Facilities</dt><dd>Sauna and both plunge pools</dd></div></dl></div>${button('Review and confirm entry','entry-review',`data-member="${m.id}"`)}`}</section></div><section class="panel space-top"><div class="section-heading"><h2>Currently inside</h2></div>${table(['Member','Entry','Leave by','Action'],activeVisits(),'No members are checked in.')}</section>`;
  }
  function members(){const people=db.users.filter(u=>u.role==='member');return pageHead('( 03 ) THE CLUB','Know your people.','Member passes, access status and visit records.')+`<div class="search-field"><label>Search members<input id="member-search" type="search" placeholder="Name, email or member number" autocomplete="off"></label></div><section class="panel">${table(['Member','Active passes','Visits','Action'],people.map(m=>`<tr data-member-row data-search="${e((m.name+' '+m.email+' '+m.number).toLowerCase())}"><td><strong data-raw>${e(m.name)}</strong><small data-raw>${e(m.email)} / ${m.number}</small></td><td>${H.currentPasses(db,m.id).length}</td><td>${db.visits.filter(v=>v.userId===m.id).length}</td><td><button class="small-button" data-action="member" data-member="${m.id}">View member</button></td></tr>`).join(''))}</section>`}
  function sales(){const total=db.orders.reduce((n,o)=>n+o.amount,0);return pageHead('( 04 ) PASSES & SALES','Every pass accounted for.','Demo purchases and the founding allocation.',button('Sell a pass','sell'))+`<div class="metric-grid three">${metric('Demo gross sales',rm(total),'No real payments')}${metric('Passes issued',db.orders.length)}${metric('Founding passes remaining',H.foundingRemaining(db),'Limited to 200 annual passes')}</div><section class="panel">${table(['Pass','Member','Purchased','Amount'],db.orders.map(o=>`<tr><td><strong>${pName(o)}</strong><small data-raw>${o.id.slice(0,11).toUpperCase()}</small></td><td data-raw>${e(name(o.userId))}</td><td>${stamp(o.at)}</td><td class="mono">${rm(o.amount)}</td></tr>`).join(''))}</section><section class="panel space-top"><div class="section-heading"><h2>Pass mix</h2></div><div class="pass-mix">${H.CATALOG.map(p=>{const orders=db.orders.filter(o=>o.productId===p.id);return `<div><span>${t(p.name)}</span><strong>${orders.length}</strong><span class="mono">${rm(orders.reduce((n,o)=>n+o.amount,0))}</span></div>`}).join('')}</div></section>`}
  function enquiries(){return pageHead('( 05 ) GROUP VISITS','Good company starts here.','Review group enquiries before confirming any arrangements.')+`<section class="panel">${db.enquiries.length?db.enquiries.map(item=>`<article class="enquiry-card"><div><p class="micro">${date(H.at(item.date,12))} / ${item.size} ${t('PEOPLE')}</p><h2 data-raw>${e(item.name)}</h2><p class="muted" data-raw>${e(item.email)}</p><p data-raw>${e(item.message||'—')}</p></div><form data-form="enquiry-status" data-id="${item.id}"><label>Status<select name="status">${['new','contacted','closed'].map(status=>`<option value="${status}" ${status===item.status?'selected':''}>${t(status[0].toUpperCase()+status.slice(1))}</option>`).join('')}</select></label><button class="small-button" type="submit">Save status</button></form></article>`).join(''):`<div class="empty-state"><h2>No enquiries yet.</h2><p>Group enquiries from this browser will appear here.</p></div>`}</section>`}
  function studioControls(){return pageHead('( 06 ) THE CONTROL PANEL','Keep the studio in balance.','Manual demo controls. Temperature targets are not live readings.')+`<div class="metric-grid three">${metric('Inside now',H.inside(db).length)}${metric('Access hours','9am–9pm')}${metric('Occupancy limit',db.settings.capacity||'—',db.settings.capacity?'Configured by admin':'Not configured')}</div><div class="staff-bottom-grid"><section class="panel"><h2>Admissions</h2><form data-form="studio-settings"><label class="checkbox"><input type="checkbox" name="paused" ${db.settings.admissionsPaused?'checked':''}><span>Pause new admissions</span></label><label>Member-facing studio note<textarea name="note" maxlength="180" rows="3" placeholder="Optional studio update">${e(db.settings.note)}</textarea></label>${isAdmin()?`<label>Occupancy limit<input name="capacity" type="number" min="1" max="200" step="1" value="${db.settings.capacity||''}" placeholder="Not configured"></label><p class="small muted">Set an approved operating limit. Pool and sauna design targets are not a combined studio capacity.</p>`:''}<p class="form-error" role="alert"></p><button class="button" type="submit">Save studio settings ${icon('arrow')}</button></form></section><section class="panel"><h2>Facilities</h2>${[['pools','Both cold-plunge pools','4°C / 8°C targets'],['sauna','Communal sauna','Shared access']].map(([id,title,note])=>`<div class="facility-control"><div><strong>${t(title)}</strong><span class="small muted">${t(note)}</span>${pill(db.settings.facilities[id]==='available'?'Available in demo':'Unavailable',db.settings.facilities[id]==='available'?'positive':'danger')}</div><button class="small-button" data-action="facility" data-facility="${id}" data-status="${db.settings.facilities[id]==='available'?'unavailable':'available'}">${t(db.settings.facilities[id]==='available'?'Mark unavailable':'Mark available')}</button></div>`).join('')}<p class="small muted">Facility changes are shown to members. Pause admissions separately when needed.</p></section></div>`}
  function nav(route){
    let items=isStaff()?[['staff-home','Today','home'],['staff-entry','Entry desk','scan'],...(canSell()?[['staff-members','Members','users'],['staff-sales','Sales','ticket'],['staff-enquiries','Enquiries','user']]:[]),['staff-studio','Studio','heat']]:user()?[['home','Home','home'],['passes','Passes','ticket'],['wallet','My passes','scan'],['visits','Visits','clock'],['account','Account','user']]:[['home','Home','home'],['passes','Passes','ticket'],['studio','Studio','heat']];
    $('#navigation').innerHTML=items.map(([id,label,ic])=>`<a href="#${id}" ${id===route?'aria-current="page"':''}>${icon(ic)}<span>${t(label)}</span></a>`).join('');
    $('#account-action').innerHTML=user()?`<a class="avatar" href="#account" aria-label="Your account">${e(user().name.split(/\s+/).map(n=>n[0]).slice(0,2).join(''))}</a>`:`<a class="sign-in-link" href="#login">${t('Sign in')} ${icon('arrow')}</a>`;
  }
  function render(){
    const u=user();if(session&&!u){session=null;try{sessionStorage.removeItem(SESSION);localStorage.removeItem(SESSION)}catch{}}
    let route=location.hash.slice(1).split('/')[0]||'home';
    if(route==='main-content')return;
    if(['wallet','visits','account'].includes(route)&&!u){returnTo=route;location.hash='login';return}
    if(route.startsWith('staff-')&&!isStaff()){location.hash=u?'home':'login';return}
    if(['staff-sales','staff-members','staff-enquiries'].includes(route)&&!canSell()){location.hash='staff-home';return}
    if(isStaff()&&['home','wallet','visits'].includes(route)){location.hash='staff-home';return}
    const pages={home,passes:catalogue,wallet,visits,studio,login:()=>auth('login'),register:()=>auth('register'),account,'staff-home':staffOverview,'staff-entry':entryDesk,'staff-members':members,'staff-sales':sales,'staff-enquiries':enquiries,'staff-studio':studioControls};
    if(!pages[route]){location.hash=isStaff()?'staff-home':'home';return}
    document.documentElement.dataset.theme=theme;document.documentElement.lang=language;
    document.title='HandC — '+t('Cold. Heat. A moment to reset.');
    document.querySelector('meta[name=theme-color]').content=theme==='day'?'#f4f4ef':'#111311';
    document.body.dataset.workspace=isStaff()?'staff':u?'member':'public';document.body.classList.toggle('auth-page',['login','register'].includes(route));
    nav(route);$('#brand-link').href=isStaff()?'#staff-home':'#home';
    $('#theme-button').innerHTML=icon(theme==='day'?'moon':'sun')+`<span>${t(theme==='day'?'Night':'Day')}</span>`;$('#theme-button').setAttribute('aria-label',t(theme==='day'?'Switch to night mode':'Switch to day mode'));
    $('#language-button').textContent=language==='en'?'繁體中文':'English';$('#language-button').setAttribute('aria-label',language==='en'?'切換為繁體中文':'Switch to English');
    const notice=[db.settings.note,db.settings.admissionsPaused?t('Admissions are temporarily paused. Please speak to reception.'):'',...Object.entries(db.settings.facilities).filter(([,s])=>s==='unavailable').map(([key])=>t(key==='pools'?'Cold-plunge pools are temporarily unavailable.':'Sauna is temporarily unavailable.'))].filter(Boolean);
    $('#studio-notice').innerHTML=notice.map(n=>`<span>${e(n)}</span>`).join('');$('#studio-notice').hidden=!notice.length;
    $('#app').innerHTML=pages[route]();translate($('#app'));
    $('#footer').innerHTML=`<div class="footer-brand"><img src="assets/logos/handc-logo.svg" alt="HandC"><span>${t('Cold. Heat. A moment to reset.')}</span></div><div class="footer-links"><span class="micro">RAJA UDA / BUTTERWORTH</span><button data-action="about">${t('About this preview')} ↗</button>${u?`<button data-action="logout">${t('Sign out')} ↗</button>`:''}</div>`;
    window.HandCExperience?.mount({translate:t});
    if(route==='login'&&u)notify('You are already signed in.');
  }
  function go(route){if(location.hash==='#'+route)render();else location.hash=route}
  function showQr(memberId=user()?.id){
    const m=db.users.find(u=>u.id===memberId&&u.role==='member');if(!m||!user()||!(isStaff()||user().id===m.id))return;
    const qr=qrcode(0,'M');qr.addData('HANDC:ENTRY:'+m.id);qr.make();
    modal('Your entry code',`<div class="qr-sheet"><span class="micro">HANDC / MEMBER ENTRY</span><h3 data-raw>${e(m.name)}</h3><div class="qr-code" role="img" aria-label="Member entry code">${qr.createSvgTag({cellSize:5,margin:20,scalable:true})}</div><strong class="mono">${m.number}</strong><p>Show your code at reception. Staff validate your pass and confirm entry.</p><p class="small muted">Showing this code does not use a pass or record a visit.</p></div>`);
  }
  function checkoutBody(p,memberId){
    const today=H.dateKey(),defaultDate=Date.now()<H.at(today,p.end)?today:H.addDays(today,1),period=p.kind==='entry'?null:p.kind==='annual'?H.anniversary(Date.now()):Date.now()+p.days*H.DAY;
    pending={productId:p.id,memberId,requestId:'buy-'+crypto.randomUUID()};
    return `<form data-form="purchase"><div class="purchase-intro"><span class="micro">${memberId===user().id?'YOUR NEXT RESET':'RECEPTION SALE'}</span><h3>${t(p.name)}</h3><strong>${rm(p.price)}</strong></div>${includes()}<dl class="fact-list"><div><dt>Access hours</dt><dd>${hours(p)}</dd></div><div><dt>Entry allowance</dt><dd>${t(p.kind==='entry'?'Single entry':'Unlimited entries')}</dd></div>${period?`<div><dt>Starts</dt><dd>At purchase</dd></div><div><dt>Duration</dt><dd>${t(p.kind==='annual'?'One year':p.days===7?'7 days':'30 days')}</dd></div>`:''}</dl>${p.kind==='entry'?`<label>Visit date<input type="date" name="visitDate" required min="${today}" max="${H.addDays(today,90)}" value="${defaultDate}"></label><p class="small muted">${t(p.end===12?'Departure by 12pm. No re-entry.':'Departure by 9pm. No re-entry.')}</p>`:`<p class="purchase-note">Validity begins when this purchase is confirmed. It runs continuously, including outside access hours.</p>`}${p.id==='founding'?`<p class="allocation-note"><span>Founding passes remaining in this demo</span>: <strong>${H.foundingRemaining(db)} / 200</strong></p>`:''}<div class="purchase-total"><span>Total</span><strong>${rm(p.price)}</strong></div><p class="small muted">Simulated purchase. No real payment is collected. Refund terms are not yet defined for the live business.</p><p class="form-error" role="alert"></p><button class="button" type="submit">Confirm demo purchase ${icon('arrow')}</button></form>`;
  }
  function buy(productId,memberId=user()?.id){
    if(!user()){returnTo='passes';try{sessionStorage.setItem('handc-pending-product',productId)}catch{}go('login');return}
    if(user().role!=='member'&&!canSell())return notify('Reception or admin access is required.');
    const p=H.product(productId);if(!p)return;
    modal('A little time, reserved for you.',checkoutBody(p,memberId));
  }
  function sell(memberId){
    if(!canSell())return;
    if(memberId)selectedMember=memberId;
    modal('Sell a pass',`<form data-form="sale-select">${memberSelect()}<label>Pass<select name="productId">${H.CATALOG.map(p=>`<option value="${p.id}" ${p.id==='founding'&&!H.foundingRemaining(db)?'disabled':''}>${t(p.name)} / ${rm(p.price)}</option>`).join('')}</select></label><button class="button" type="submit">Review purchase ${icon('arrow')}</button></form>`);
  }
  function entryReview(memberId){
    if(!isStaff())return;const preview=H.entryPreview(db,memberId);
    if(preview.error){notify(failMessage(preview.error),'error');render();return}
    modal('Confirm this entry?',`<div class="entry-confirm"><h3 data-raw>${e(name(memberId))}</h3><p>${pName(preview.pass)}</p><dl class="fact-list"><div><dt>Leave by</dt><dd>${stamp(preview.leaveBy)}</dd></div><div><dt>Entry allowance</dt><dd>${t(preview.product.kind==='entry'?'This single entry will be used.':'Unlimited entries. Membership stays active.')}</dd></div></dl><p class="small muted">${t(preview.product.end===12?'Sunrise visitors must leave by 12pm.':'All visitors must leave by their pass deadline.')}</p>${button('Confirm entry','confirm-entry',`data-member="${memberId}"`)}</div>`);
  }
  function findMember(raw){const code=String(raw).trim();let key=code;if(code.startsWith('HANDC:ENTRY:'))key=code.slice(12);return db.users.find(u=>u.role==='member'&&u.active!==false&&(u.id===key||u.number.toLowerCase()===key.toLowerCase()))}
  async function startCamera(){
    if(!isStaff())return;
    if(!navigator.mediaDevices?.getUserMedia)return notify('Camera unavailable. Use the member number instead.');
    stopCamera();
    const requestId=crypto.randomUUID();$('#scan-video').dataset.request=requestId;
    try{
      const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});
      if(!$('#modal').open||$('#scan-video')?.dataset.request!==requestId){stream.getTracks().forEach(track=>track.stop());return}
      camera=stream;const video=$('#scan-video');video.srcObject=stream;await video.play();
      $('#scan-message').textContent=t('Point the camera at the member code.');
      const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});
      const scan=()=>{if(!camera||!$('#modal').open)return;if(video.readyState>=2&&video.videoWidth){canvas.width=video.videoWidth;canvas.height=video.videoHeight;ctx.drawImage(video,0,0);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),result=jsQR(pixels.data,pixels.width,pixels.height,{inversionAttempts:'dontInvert'});if(result){const m=findMember(result.data);if(m){stopCamera();closeModal();selectedMember=m.id;go('staff-entry');entryReview(m.id);return}$('#scan-message').textContent=t('Member not found. Try the member number.')}}frame=requestAnimationFrame(scan)};frame=requestAnimationFrame(scan);
    }catch{stopCamera();if($('#scan-message'))$('#scan-message').textContent=t('Camera access was unavailable. Use the member number instead.')}
  }
  function scanModal(){if(!isStaff())return;modal('Scan member entry code',`<video id="scan-video" playsinline muted></video><p id="scan-message" class="muted">Start the camera or enter the member number.</p>${button('Start camera','camera','','secondary')}<form data-form="scan-code" class="space-top"><label>Member number or QR content<input name="code" placeholder="HC0001" required maxlength="180" autocomplete="off"></label><p class="form-error" role="alert"></p><button class="button" type="submit">Review access ${icon('arrow')}</button></form>`)}
  async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const result=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256);return [...new Uint8Array(result)].map(b=>b.toString(16).padStart(2,'0')).join('')}
  function resumePurchase(account){
    let productId;try{productId=sessionStorage.getItem('handc-pending-product');sessionStorage.removeItem('handc-pending-product')}catch{}
    if(productId&&account.role==='member')setTimeout(()=>buy(productId),0);
  }
  async function signIn(form,values){
    const email=String(values.get('email')).trim().toLowerCase(),password=String(values.get('password')),account=db.users.find(u=>u.email.toLowerCase()===email&&u.active!==false);
    const valid=account&&(account.credential?await passwordHash(password,account.credential.salt)===account.credential.hash:password===PASSWORD);
    if(!valid)throw new Error(t('Email or password is incorrect.'));
    session={userId:account.id};sessionStorage.setItem(SESSION,JSON.stringify(session));
    if(values.get('remember'))localStorage.setItem(SESSION,JSON.stringify(session));else localStorage.removeItem(SESSION);
    closeModal();go(H.staff(account)?'staff-home':returnTo||'home');returnTo='home';
    resumePurchase(account);
  }
  document.addEventListener('click',async event=>{
    const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
    try{
      if(action==='skip'){event.preventDefault();$('#app').focus();return}
      if(action==='close')return closeModal();
      if(action==='theme'){theme=theme==='day'?'night':'day';try{localStorage.setItem('handc-theme',theme)}catch{}document.documentElement.dataset.theme=theme;$$('[data-scene]').filter(el=>el.tagName==='IMG').forEach(img=>{img.src=`assets/studio/${img.dataset.scene}-${theme}.webp`});render();return}
      if(action==='language'){language=language==='en'?'zh-TW':'en';try{localStorage.setItem('handc-locale',language)}catch{}render();if($('#modal').open)closeModal();return}
      if(action==='buy')return buy(target.dataset.product);
      if(action==='sell')return sell(target.dataset.member);
      if(action==='qr')return showQr(target.dataset.member||user()?.id);
      if(action==='scene'){scene=target.dataset.scene;render();return}
      if(action==='password'){const field=target.closest('.password-input').querySelector('input');field.type=field.type==='password'?'text':'password';target.setAttribute('aria-label',t(field.type==='password'?'Show password':'Hide password'));return}
      if(action==='demo-fill'){const u=db.users.find(u=>u.id===target.dataset.member);$('#auth-form [name=email]').value=u.email;$('#auth-form [name=password]').value=PASSWORD;$('#auth-form button[type=submit]').focus();return}
      if(action==='logout'){session=null;sessionStorage.removeItem(SESSION);localStorage.removeItem(SESSION);closeModal();go('home');render();return}
      if(action==='about')return modal('A clear look at this preview.',`<div class="prose"><p>This is the HandC thermal wellness prototype for Raja Uda, Butterworth.</p><p>Purchases, admissions, sales, member records and the 200-pass allocation are simulated in this browser. They are not shared across devices. There are no real payments or messages.</p><p>Every pass includes the sauna and both plunge pools. Day passes allow one entry. Weekly, monthly and annual passes allow unlimited entries during access hours, with validity beginning at purchase.</p><p>Studio images are concept visuals. Pool temperatures are design targets. The final address, contact channels, refreshments menu, refund terms and operating capacity remain to be confirmed.</p><a class="text-link" href="https://handc-business-summary.vercel.app/" target="_blank" rel="noopener noreferrer">Read the business concept ↗</a></div>`);
      if(action==='group')return modal('A shared reset.',`<form data-form="group"><p class="muted">Tell reception about your preferred visit. This enquiry does not reserve places.</p><label>Full name<input name="name" required minlength="2" maxlength="60" value="${e(user()?.name||'')}" autocomplete="name"></label><label>Email address<input name="email" type="email" required maxlength="100" value="${e(user()?.email||'')}" autocomplete="email"></label><div class="form-grid"><label>Group size<input name="size" type="number" min="2" max="100" value="2" required></label><label>Preferred date<input name="date" type="date" min="${H.dateKey()}" required></label></div><label>Anything to share?<textarea name="message" maxlength="1000" rows="3"></textarea></label><p class="small muted">This saves a demo enquiry on this device. No message is sent to the studio.</p><p class="form-error" role="alert"></p><button class="button" type="submit">Save demo enquiry ${icon('arrow')}</button></form>`);
      if(action==='pass-details'){const p=db.passes.find(p=>p.id===target.dataset.pass);if(!p||!(isStaff()||user()?.id===p.userId))return;return modal('Pass details',`<h3>${pName(p)}</h3><dl class="fact-list"><div><dt>Purchased</dt><dd>${stamp(p.purchasedAt)}</dd></div><div><dt>Access hours</dt><dd>${hours(H.product(p.productId))}</dd></div><div><dt>Valid until</dt><dd>${stamp(p.validUntil)}</dd></div><div><dt>Status</dt><dd>${statusLabel(H.passState(p))}</dd></div></dl>${includes()}`)}
      if(action==='entry-review')return entryReview(target.dataset.member);
      if(action==='confirm-entry'){target.disabled=true;await update(db=>H.checkIn(db,target.dataset.member,user()?.id));closeModal();render();return notify('Entry confirmed.','success')}
      if(action==='checkout'){if(!isStaff())return;const v=db.visits.find(v=>v.id===target.dataset.visit);if(!v)return;return modal('Confirm departure?',`<h3 data-raw>${e(name(v.userId))}</h3><p>${t('Entered')} ${time(v.inAt)} / ${pName(v)}</p><p class="muted">This closes the current visit. A valid duration pass can be used again during access hours.</p>${button('Confirm departure','confirm-checkout',`data-visit="${v.id}"`)}`)}
      if(action==='confirm-checkout'){target.disabled=true;await update(db=>H.checkOut(db,target.dataset.visit,user()?.id));closeModal();render();return notify('Departure recorded.','success')}
      if(action==='scan')return scanModal();if(action==='camera')return startCamera();
      if(action==='facility'){await update(db=>H.updateStudio(db,user()?.id,{facility:target.dataset.facility,status:target.dataset.status}));render();return notify('Facility status saved.','success')}
      if(action==='member'){if(!canSell())return;const m=db.users.find(u=>u.id===target.dataset.member);if(!m)return;return modal('Member record',`<h3 data-raw>${e(m.name)}</h3><p class="muted" data-raw>${e(m.email)} / ${m.number}</p><div class="record-list">${db.passes.filter(p=>p.userId===m.id).map(p=>`<article><div><strong>${pName(p)}</strong><p class="small muted">${stamp(p.validUntil)}</p></div>${pill(statusLabel(H.passState(p)))}</article>`).join('')||'<p>No passes yet.</p>'}</div><div class="actions">${button('Show entry code','qr',`data-member="${m.id}"`,'secondary')}${button('Sell a pass','sell',`data-member="${m.id}"`)}</div>`)}
    }catch(error){notify(error.code?failMessage(error.code):error.message,'error');target.disabled=false}
  });
  document.addEventListener('submit',async event=>{
    const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();if(form.dataset.busy)return;
    const submit=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');if(error)error.textContent='';form.dataset.busy='true';form.setAttribute('aria-busy','true');if(submit)submit.disabled=true;
    const values=new FormData(form);
    try{
      switch(form.dataset.form){
        case 'login':await signIn(form,values);break;
        case 'register':{
          const name=String(values.get('name')).trim(),email=String(values.get('email')).trim().toLowerCase(),password=String(values.get('password'));
          if(name.length<2||name.length>60||!/^\S+@\S+\.\S+$/.test(email)||password.length<8)throw new Error(t('Check your name, email and demo password.'));
          const salt=crypto.randomUUID(),hash=await passwordHash(password,salt),newId='member-'+crypto.randomUUID();
          await update(current=>{if(current.users.some(u=>u.email.toLowerCase()===email))throw new Error(t('This email already has an account.'));const next=structuredClone(current);next.users.push({id:newId,name,email,number:'HC'+String(1+next.users.filter(u=>u.role==='member').length).padStart(4,'0'),role:'member',active:true,credential:{salt,hash}});return next});
          session={userId:newId};sessionStorage.setItem(SESSION,JSON.stringify(session));localStorage.removeItem(SESSION);go('home');returnTo='home';resumePurchase(user());break;
        }
        case 'purchase':{
          const draft=pending;if(!draft)throw new Error(t('Please start the purchase again.'));
          const result=await update(current=>H.purchase(current,draft.memberId,draft.productId,{actorId:user()?.id,requestId:draft.requestId,visitDate:String(values.get('visitDate')||H.dateKey())}));
          closeModal();render();window.HandCExperience?.feedback('success');modal('Your pass is ready.',`<div class="purchase-success">${icon('check')}<h3>${pName(result.pass||{productId:result.order.productId})}</h3><p class="mono">${rm(result.order.amount)}</p><p>${t('Purchased for')} <span data-raw>${e(name(result.order.userId))}</span></p><p class="muted">${t('Valid until')} ${stamp((result.pass||db.passes.find(p=>p.id===result.order.passId)).validUntil)}</p><p class="small muted">Demo purchase complete. No payment was collected.</p>${user()?.role==='member'?link('View my passes','wallet'):button('Return to sales','sales-return')}</div>`);break;
        }
        case 'sale-select':{if(!canSell())throw new Error(t('Reception or admin access is required.'));selectedMember=String(values.get('memberId'));buy(String(values.get('productId')),selectedMember);break}
        case 'entry-member':selectedMember=String(values.get('memberId'));render();break;
        case 'lookup':case 'scan-code':{if(!isStaff())return;const m=findMember(values.get('code'));if(!m)throw new Error(t('Member not found. Try the member number.'));selectedMember=m.id;closeModal();go('staff-entry');render();if(form.dataset.form==='scan-code')entryReview(m.id);break}
        case 'profile':{const name=String(values.get('name')).trim(),phone=String(values.get('phone')).trim();if(name.length<2||name.length>60||phone.length>24)throw new Error(t('Check your profile details.'));await update(current=>{const next=structuredClone(current),u=H.actor(next,user()?.id);if(!u)throw new Error('Sign in required.');u.name=name;u.phone=phone;return next});render();notify('Profile saved.','success');break}
        case 'group':await update(current=>H.createEnquiry(current,Object.fromEntries(values)));closeModal();notify('Demo enquiry saved. No message was sent.','success');break;
        case 'enquiry-status':await update(current=>H.updateEnquiry(current,form.dataset.id,String(values.get('status')),user()?.id));render();notify('Enquiry status saved.','success');break;
        case 'studio-settings':{const settings={admissionsPaused:values.has('paused'),note:String(values.get('note'))};if(isAdmin())settings.capacity=values.get('capacity')?Number(values.get('capacity')):null;await update(current=>H.updateStudio(current,user()?.id,settings));render();notify('Studio settings saved.','success');break}
      }
    }catch(err){if(error){error.textContent=err.code?failMessage(err.code):err.message;window.HandCExperience?.feedback('error')}else notify(err.code?failMessage(err.code):err.message,'error')}
    finally{delete form.dataset.busy;form.removeAttribute('aria-busy');if(submit?.isConnected)submit.disabled=false}
  });
  document.addEventListener('click',event=>{if(event.target.closest('[data-action="sales-return"]')){closeModal();go('staff-sales')}});
  document.addEventListener('input',event=>{if(event.target.id==='member-search'){const query=event.target.value.trim().toLowerCase();$$('[data-member-row]').forEach(row=>row.hidden=!row.dataset.search.includes(query))}});
  window.addEventListener('hashchange',()=>{if(location.hash==='#main-content'){$('#app').focus();return}closeModal();render();window.scrollTo({top:0,behavior:'instant'});$('#app h1')?.focus({preventScroll:true})});
  window.addEventListener('storage',event=>{if(event.key===STORE){try{const next=JSON.parse(event.newValue);if(H.validDatabase(next)){db=next;if(!$('#modal').open)render()}}catch{}}});
  window.addEventListener('pagehide',stopCamera);
  setInterval(()=>{$$('[data-clock]').forEach(el=>el.textContent=stamp(Date.now()))},30000);
  render();
})();
